public class Main {
    static final long HUGE_INF = 17446744073709551616L;
    static long M, N, K;
    static long[][] dp_table = new long[18][250005];
    static long[] fact = new long[250005];
    static long[] inv_fact = new long[250005];

    static long fastExponent(long base, long exp) {
        long res = 1L;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1L) == 1L) res = (res * cur) % M;
            cur = (cur * cur) % M;
            exp >>= 1;
        }
        return res;
    }

    static long nChoose(int a, int b) {
        return (((fact[a] * inv_fact[b]) % M) * inv_fact[a - b]) % M;
    }

    static long compute() {
        int i, j, mask;
        fact[0] = 1L;
        for (i = 1; i <= N; i++) {
            fact[i] = (fact[i - 1] * i) % M;
        }
        inv_fact[N] = fastExponent(fact[N], M - 2);
        for (i = N - 1; i >= 0; i--) {
            inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % M;
        }
        for (i = 1; i <= N; i++) {
            dp_table[1][i] = inv_fact[i];
