            total += dp_table[i][N] * nChoose((int)K, i);
            total %= M;
        }
        total = (total * fact[(int)N]) % M;
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextLong();
